import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.HashMap;import java.util.Map;import java.util.StringTokenizer;public class TestClass {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String line = br.readLine();if (line == null) return;int t = Integer.parseInt(line.trim());while (t-- > 0) {int n = Integer.parseInt(br.readLine().trim());StringTokenizer st = new StringTokenizer(br.readLine());Map<Integer, Long> counts = new HashMap<>();for (int i = 1; i <= n; i++) {int val = Integer.parseInt(st.nextToken());int transformed = val ^ i;counts.put(transformed, counts.getOrDefault(transformed, 0L) + 1);}long totalPairs = 0;for (long count : counts.values()) {if (count > 1) {totalPairs += (count * (count - 1)) / 2;}}System.out.println(totalPairs);}}}